package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen1Test {

    private Element root;
    private String baseUri = "http://example.com";

    @Before
    public void setUp() {
        root = new Element("div", baseUri);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testPrepend_NullHtml() {
        root.prepend(null);
    }

    @Test
    public void testPrepend_EmptyHtml() {
        root.prepend("");
        assertEquals("", root.html());
    }

    @Test
    public void testPrepend_SimpleText() {
        root.prepend("Hello");
        assertEquals("Hello<div></div>", root.html());
    }

    @Test
    public void testPrepend_SimpleElement() {
        root.prepend("<span>World</span>");
        assertEquals("<span>World</span><div></div>", root.html());
    }

    @Test
    public void testPrepend_MultipleElements() {
        root.prepend("<span>First</span><div>Second</div>");
        assertEquals("<span>First</span><div>Second</div><div></div>", root.html());
    }

    @Test
    public void testPrepend_MixedContent() {
        root.prepend("Text <b>Bold</b> More Text");
        assertEquals("Text <b>Bold</b> More Text<div></div>", root.html());
    }

    @Test
    public void testPrepend_NestedElements() {
        root.prepend("<div><p>Nested</p></div>");
        assertEquals("<div><p>Nested</p></div><div></div>", root.html());
    }

    @Test
    public void testPrepend_Attributes() {
        root.prepend("<a href='http://example.com'>Link</a>");
        assertEquals("<a href=\"http://example.com\">Link</a><div></div>", root.html());
    }

    @Test
    public void testPrepend_WithBaseUri() {
        Element customBase = new Element("base", baseUri, "href", "http://custom.com");
        customBase.prepend("<a href='path'>Link</a>");
        assertEquals("<a href=\"http://custom.com/path\">Link</a><base href=\"http://custom.com\"></base>", customBase.html());
    }
}
